            C++

    #include <iostream>
#include <map>
#include <vector>
using namespace std;

int countAllDistinct(vector<int> &arr)
{
    int n = arr.size();
    unordered_map<int, int> vis;

    // count total distinct elements
    for (int x : arr)
        vis[x] = 1;

    int k = vis.size();
    vis.clear();

    int ans = 0, right = 0, window = 0;

    for (int left = 0; left < n; left++)
    {

        // expand window until all distinct elements are included
        while (right < n && window < k)
        {
            vis[arr[right]]++;

            if (vis[arr[right]] == 1)
                window++;

            right++;
        }

        // if valid window, count subarrays
        if (window == k)
            ans += (n - right + 1);

        // shrink window from left
        vis[arr[left]]--;

        if (vis[arr[left]] == 0)
            window--;
    }

    return ans;
}

int main()
{

    vector<int> arr = {2, 4, 4, 2, 4};

    cout << countAllDistinct(arr);
    return 0;
}


